var CONFIG = {
  BATCH_NUMBER: -1,
  HEADER_SCORE_THRESHOLD: 5,
  MAX_ARTICLE_AGE_HOURS: 48,
  CLASSIFICATION_BATCH_SIZE: 30,
};
return [{ json: CONFIG }];

var config = $('Config').first().json;
var feeds = $input.all();
var filtered;
if (config.BATCH_NUMBER === -1) {
  filtered = feeds;
} else {
  filtered = feeds.filter(function(f) {
    return f.json.batch_number === config.BATCH_NUMBER;
  });
}
if (filtered.length === 0) {
  throw new Error('No active feeds found for batch ' + config.BATCH_NUMBER);
}
return filtered;

var feedData = $('Loop Feeds').first().json;
var config = $('Config').first().json;
var items = $input.all();
var now = new Date();
var maxAge = config.MAX_ARTICLE_AGE_HOURS * 60 * 60 * 1000;
var results = [];
for (var i = 0; i < items.length; i++) {
  var item = items[i];
  if (item.json.error) continue;
  var pubDate = new Date(item.json.isoDate || item.json.pubDate || now);
  var age = now - pubDate;
  if (age > maxAge) continue;
  results.push({
    json: {
      title: item.json.title || '',
      description: item.json.contentSnippet || item.json.content || '',
      url: item.json.link || item.json.guid || '',
      pubDate: item.json.isoDate || item.json.pubDate || now.toISOString(),
      feed_id: feedData.id,
      feed_name: feedData.name,
      feed_category: feedData.category,
      feed_url: feedData.url
    }
  });
}
if (results.length === 0) {
  return [{ json: { _skip: true, feed_name: feedData.name } }];
}
return results;

var allItems = $('Attach Feed Info').all();
var headers = allItems.filter(function(item) {
  return !item.json._skip && item.json.title;
});
if (headers.length === 0) {
  return [{ json: { total_headers: 0, headers: [] } }];
}
return [{
  json: {
    total_headers: headers.length,
    headers: headers.map(function(h) { return h.json; })
  }
}];

var existingItems = $('Get Existing URLs').all();
var existingUrls = {};
for (var i = 0; i < existingItems.length; i++) {
  var u = existingItems[i].json.url;
  if (u) existingUrls[u] = true;
}
var allHeaders = $('Merge + Filter').first().json.headers;
var newHeaders = allHeaders.filter(function(h) {
  return !existingUrls[h.url];
});
return [{
  json: {
    total_new: newHeaders.length,
    total_skipped: allHeaders.length - newHeaders.length,
    headers: newHeaders
  }
}];

var config = $('Config').first().json;
var data = $input.first().json;
var headers = data.headers;
var batchSize = config.CLASSIFICATION_BATCH_SIZE;
var batches = [];
for (var i = 0; i < headers.length; i += batchSize) {
  batches.push({
    json: {
      batch_index: Math.floor(i / batchSize),
      batch_size: Math.min(batchSize, headers.length - i),
      headlines: headers.slice(i, i + batchSize)
    }
  });
}
if (batches.length === 0) {
  return [{ json: { headlines: [], batch_index: 0, batch_size: 0 } }];
}
return batches;

var batch = $json;
var headlines = batch.headlines;
var headlineList = headlines.map(function(h, i) {
  var title = (h.title || '').replace(/"/g, "'").substring(0, 150);
  var desc = (h.description || '').replace(/"/g, "'").substring(0, 200);
  return (i + 1) + '. "' + title + '" -- ' + desc;
}).join('\n');
var prompt = 'Classify these news headlines for Brett Moore podcast Fasten Your Seatbelt. ';
prompt += 'Brett covers geopolitics, science/tech, economics, and quirky/surprising stories.\n\n';
prompt += 'For each headline return a JSON array. Each item must have:\n';
prompt += '- index: headline number (1-based)\n';
prompt += '- category: one of [politics, geopolitics, science, tech, economics, quirky, other]\n';
prompt += '- relevance: 1-10 how relevant to Brett\n';
prompt += '- tags: object with keys entities (people/orgs/places), topics (themes), events (what happened)\n';
prompt += '- extract: true if worth reading full article, false to skip\n';
prompt += '- confidence: 0-1 how sure you are\n\n';
prompt += 'Headlines:\n' + headlineList + '\n\nReturn ONLY the JSON array.';
return [{
  json: {
    headlines: batch.headlines,
    batch_index: batch.batch_index,
    batch_size: batch.batch_size,
    classify_prompt: prompt
  }
}];

var response = $input.first().json;
var batchData = $('Build Prompt').item.json;
var headlines = batchData.headlines;
var classified = [];
try {
  var content = response.text || '[]';
  var fence = String.fromCharCode(96,96,96); content = content.replace(new RegExp(fence + 'json', 'g'), '').replace(new RegExp(fence, 'g'), '');
  var jsonMatch = content.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    classified = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  classified = headlines.map(function(h, i) {
    return {
      index: i + 1, category: 'other', relevance: 5,
      tags: { entities: [], topics: [], events: [] },
      extract: true, confidence: 0
    };
  });
}
var results = headlines.map(function(h, i) {
  var cls = null;
  for (var j = 0; j < classified.length; j++) {
    if (classified[j].index === i + 1) { cls = classified[j]; break; }
  }
  if (!cls) cls = classified[i] || {
    category: 'other', relevance: 5,
    tags: { entities: [], topics: [], events: [] },
    extract: true, confidence: 0
  };
  return {
    json: {
      title: h.title,
      description: h.description,
      url: h.url,
      pubDate: h.pubDate,
      feed_id: h.feed_id,
      feed_name: h.feed_name,
      feed_category: h.feed_category,
      category: cls.category || h.feed_category || 'other',
      header_score: cls.relevance || 5,
      tags: cls.tags || { entities: [], topics: [], events: [] },
      extract_worthy: cls.extract !== false,
      confidence: cls.confidence || 0,
      status: (cls.extract !== false) ? 'extract_worthy' : 'header_scored'
    }
  };
});
return results;

var config = $('Config').first().json;
var allArticles = $('Parse Classifications').all().map(function(i) { return i.json; });

// ---- FIX: Use feed_category as fallback for diversity ----
// Keep geopolitics as its own category — do NOT collapse to politics
var feedCatMap = {
  'world_news': 'geopolitics',
  'politics': 'politics',
  'geopolitics': 'geopolitics',
  'science': 'science',
  'technology': 'tech',
  'tech': 'tech',
  'economics': 'economics',
  'finance': 'economics',
  'quirky': 'quirky',
  'longform': 'quirky',
  'culture': 'quirky',
  'australia': 'geopolitics',
  'canada': 'geopolitics'
};

// If LLM classified as politics/other but feed_category suggests otherwise, trust the feed
for (var fi = 0; fi < allArticles.length; fi++) {
  var art = allArticles[fi];
  var llmCat = art.category || 'other';
  var feedCat = art.feed_category || '';
  var mappedFeedCat = feedCatMap[feedCat.toLowerCase()] || '';
  if ((llmCat === 'politics' || llmCat === 'other') && mappedFeedCat && mappedFeedCat !== 'politics') {
    art.category = mappedFeedCat;
  }
  if (llmCat === 'other' && mappedFeedCat) {
    art.category = mappedFeedCat;
  }
}

// ---- CLUSTERING BY TAGS ----
var clusters = {};
var clusterCounter = 0;
for (var i = 0; i < allArticles.length; i++) {
  var a = allArticles[i];
  var aEntities = (a.tags && a.tags.entities ? a.tags.entities : []).map(function(t) { return t.toLowerCase(); });
  var aEvents = (a.tags && a.tags.events ? a.tags.events : []).map(function(t) { return t.toLowerCase(); });
  var aTags = aEntities.concat(aEvents);
  var foundCluster = null;
  var clusterKeys = Object.keys(clusters);
  for (var ci = 0; ci < clusterKeys.length; ci++) {
    var cId = clusterKeys[ci];
    var cluster = clusters[cId];
    var sharedEntities = aEntities.filter(function(t) { return cluster.entities.indexOf(t) >= 0; });
    var sharedEvents = aEvents.filter(function(t) { return cluster.events.indexOf(t) >= 0; });
    var shared = aTags.filter(function(t) { return cluster.tags.indexOf(t) >= 0; });
    if ((sharedEntities.length >= 1 && sharedEvents.length >= 1) || shared.length >= 3) {
      foundCluster = cId;
      break;
    }
  }
  if (foundCluster) {
    clusters[foundCluster].articles.push(i);
    var merged = clusters[foundCluster].tags.concat(aTags);
    clusters[foundCluster].tags = merged.filter(function(v, idx, arr) { return arr.indexOf(v) === idx; });
    var mEnt = clusters[foundCluster].entities.concat(aEntities);
    clusters[foundCluster].entities = mEnt.filter(function(v, idx, arr) { return arr.indexOf(v) === idx; });
    var mEv = clusters[foundCluster].events.concat(aEvents);
    clusters[foundCluster].events = mEv.filter(function(v, idx, arr) { return arr.indexOf(v) === idx; });
  } else {
    var newId = 'cluster_' + (clusterCounter++);
    clusters[newId] = {
      articles: [i],
      tags: aTags.filter(function(v, idx, arr) { return arr.indexOf(v) === idx; }),
      entities: aEntities.filter(function(v, idx, arr) { return arr.indexOf(v) === idx; }),
      events: aEvents.filter(function(v, idx, arr) { return arr.indexOf(v) === idx; })
    };
  }
}

// Assign cluster info + compute cluster_score
var clusterKeys2 = Object.keys(clusters);
for (var ci2 = 0; ci2 < clusterKeys2.length; ci2++) {
  var cId2 = clusterKeys2[ci2];
  var cl = clusters[cId2];
  cl.articles.sort(function(a, b) {
    return (allArticles[b].header_score || 0) - (allArticles[a].header_score || 0);
  });
  for (var r = 0; r < cl.articles.length; r++) {
    var idx = cl.articles[r];
    allArticles[idx].cluster_id = cId2;
    allArticles[idx].cluster_rank = r + 1;
    allArticles[idx].source_count = cl.articles.length;
    var pubMs = new Date(allArticles[idx].pubDate).getTime();
    var ageHours = (Date.now() - pubMs) / 3600000;
    var freshness = ageHours < 6 ? 1.5 : (ageHours < 12 ? 1.2 : (ageHours < 24 ? 1.0 : 0.8));
    allArticles[idx].cluster_score = (allArticles[idx].header_score || 5) * Math.log(cl.articles.length + 1) * freshness;
  }
}

// ---- DIVERSITY-AWARE TOP SELECTION ----
var candidates = allArticles.filter(function(a) {
  return a.cluster_rank === 1 && a.extract_worthy && (a.header_score || 0) >= config.HEADER_SCORE_THRESHOLD;
});
candidates.sort(function(a, b) { return (b.cluster_score || 0) - (a.cluster_score || 0); });

// Relaxed pool for diversity fills (lower threshold)
var relaxedCandidates = allArticles.filter(function(a) {
  return a.cluster_rank === 1 && (a.header_score || 0) >= Math.max(config.HEADER_SCORE_THRESHOLD - 2, 1);
});
relaxedCandidates.sort(function(a, b) { return (b.cluster_score || 0) - (a.cluster_score || 0); });

// Category diversity - guarantee at least 1 per category (now includes geopolitics)
var categories = ['politics', 'geopolitics', 'science', 'tech', 'economics', 'quirky', 'other'];
var picked = [];
var pickedUrls = {};

// First pass: pick best from each category (strict then relaxed)
for (var ci3 = 0; ci3 < categories.length; ci3++) {
  var cat = categories[ci3];
  var found = false;
  for (var pi = 0; pi < candidates.length; pi++) {
    if (candidates[pi].category === cat && !pickedUrls[candidates[pi].url]) {
      picked.push(candidates[pi]);
      pickedUrls[candidates[pi].url] = true;
      found = true;
      break;
    }
  }
  if (!found) {
    for (var ri = 0; ri < relaxedCandidates.length; ri++) {
      if (relaxedCandidates[ri].category === cat && !pickedUrls[relaxedCandidates[ri].url]) {
        picked.push(relaxedCandidates[ri]);
        pickedUrls[relaxedCandidates[ri].url] = true;
        break;
      }
    }
  }
}

// Second pass: round-robin by category, least represented first
var catCounts = {};
for (var pc = 0; pc < picked.length; pc++) {
  var pCat = picked[pc].category || 'other';
  catCounts[pCat] = (catCounts[pCat] || 0) + 1;
}

// Build per-category queues from remaining candidates
var catQueues = {};
for (var qi = 0; qi < candidates.length; qi++) {
  var qCat = candidates[qi].category || 'other';
  if (!pickedUrls[candidates[qi].url]) {
    if (!catQueues[qCat]) catQueues[qCat] = [];
    catQueues[qCat].push(candidates[qi]);
  }
}

// Fill to 30 via round-robin (least represented category first each round)
while (picked.length < 30) {
  // Sort categories by current count ascending
  var sortedCats = categories.slice().sort(function(a, b) {
    return (catCounts[a] || 0) - (catCounts[b] || 0);
  });
  var addedThisRound = false;
  for (var sci = 0; sci < sortedCats.length && picked.length < 30; sci++) {
    var sCat = sortedCats[sci];
    if (catQueues[sCat] && catQueues[sCat].length > 0) {
      var next = catQueues[sCat].shift();
      picked.push(next);
      pickedUrls[next.url] = true;
      catCounts[sCat] = (catCounts[sCat] || 0) + 1;
      addedThisRound = true;
    }
  }
  if (!addedThisRound) break;
}

var trending = clusterKeys2.filter(function(cId) {
  return clusters[cId].articles.length >= 3;
}).map(function(cId) {
  return { cluster_id: cId, source_count: clusters[cId].articles.length, tags: clusters[cId].tags.slice(0, 5) };
});

return [{
  json: {
    total_classified: allArticles.length,
    total_clusters: clusterKeys2.length,
    total_trending: trending.length,
    total_picked: picked.length,
    trending: trending,
    all_articles: allArticles,
    top_candidates: picked
  }
}];

var scoreData = $('Cluster + Score').first().json;
var allArticles = scoreData.all_articles || [];
var items = [];
for (var i = 0; i < allArticles.length; i++) {
  var a = allArticles[i];
  items.push({
    json: {
      url: a.url || '',
      title: (a.title || '').substring(0, 500),
      source_name: a.feed_name || 'RSS',
      source_type: 'rss',
      category: a.category || 'other',
      composite_score: a.header_score || 0,
      header_score: a.header_score || 0,
      source_count: a.source_count || 1,
      status: 'header_scored',
      metadata: JSON.stringify({
        tags: a.tags || {},
        cluster_id: a.cluster_id || '',
        cluster_rank: a.cluster_rank || 1,
        confidence: a.confidence || 0,
        feed_id: a.feed_id || '',
        feed_name: a.feed_name || '',
        description: (a.description || '').substring(0, 1000)
      })
    }
  });
}
if (items.length === 0) items.push({json: {_empty: true}});
return items;
